// This code has been fully generated by an AI.
//
// Theme switching and theme colors for canvas-based charts.

import { THEME_KEY, normalizeTheme } from "./theme-data.js";

const media = matchMedia("(prefers-color-scheme: dark)");
const EVENT = "myvelo:theme";

function stored() {
  try {
    return normalizeTheme(localStorage.getItem(THEME_KEY));
  } catch {
    return "light";
  }
}

export function setTheme(theme) {
  theme = normalizeTheme(theme);
  document.documentElement.dataset.theme = theme;
  try {
    localStorage.setItem(THEME_KEY, theme);
  } catch {
    // Storage may be blocked in the ingress iframe; the choice then lasts for this page.
  }
  document.dispatchEvent(new CustomEvent(EVENT));
}

/** Wires radio buttons name="theme" inside el to the stored theme. */
export function initThemeSwitch(el) {
  const current = stored();
  for (const input of el.querySelectorAll("input[name=theme]")) {
    input.checked = input.value === current;
    input.addEventListener("change", () => input.checked && setTheme(input.value));
  }
}

/** Reads the chart colors from the CSS custom properties. */
export function chartColors() {
  const css = getComputedStyle(document.documentElement);
  const v = (name) => css.getPropertyValue(name).trim();
  return {
    axis: v("--chart-axis"),
    grid: v("--chart-grid"),
    accent: v("--accent"),
    muted: v("--text-muted"),
    surface: v("--surface"),
    series: {
      alt: v("--chart-alt"),
      speed: v("--chart-speed"),
      hr: v("--chart-hr"),
      power: v("--chart-power"),
      cad: v("--chart-cad"),
      temp: v("--chart-temp"),
    },
    years: [1, 2, 3, 4, 5].map((i) => v(`--chart-year-${i}`)),
  };
}

/** Calls fn whenever the effective theme may have changed. */
export function onThemeChange(fn) {
  document.addEventListener(EVENT, fn);
  media.addEventListener("change", () => document.documentElement.dataset.theme === "system" && fn());
}
